MINI(4, 'Membaca hasil A/B test halaman checkout',
  'Tim produk mengubah tombol checkout. Versi B tampak lebih banyak konversinya. Apakah perbedaan ini nyata atau kebetulan, dan seberapa besar dampaknya?',
  ['Hitung tingkat konversi tiap versi', 'Uji dua proporsi (z-test) dan p-value', 'Selang kepercayaan 95% untuk selisih konversi', 'Rekomendasi dalam bahasa bisnis, termasuk perkiraan tambahan pesanan per bulan'],
  ['Konversi = jumlah membeli ÷ jumlah pengunjung.', 'Hitung proporsi gabungan dan galat baku; z = selisih ÷ galat baku; p-value dua sisi dari distribusi normal.', 'Selang kepercayaan selisih: selisih ± 1,96 × galat baku (tanpa penggabungan).', 'Terjemahkan ke dampak: selisih × pengunjung bulanan. Sebutkan juga batas bawahnya agar tidak terlalu optimis.'],
  "from math import sqrt, erf\n\nA = {'pengunjung': 8200, 'beli': 287}\nB = {'pengunjung': 8150, 'beli': 342}\npa, pb = A['beli'] / A['pengunjung'], B['beli'] / B['pengunjung']\n\np = (A['beli'] + B['beli']) / (A['pengunjung'] + B['pengunjung'])\nse0 = sqrt(p * (1 - p) * (1 / A['pengunjung'] + 1 / B['pengunjung']))\nz = (pb - pa) / se0\nphi = lambda x: 0.5 * (1 + erf(x / sqrt(2)))\np_value = 2 * (1 - phi(abs(z)))\n\nse = sqrt(pa * (1 - pa) / A['pengunjung'] + pb * (1 - pb) / B['pengunjung'])\nbawah, atas = (pb - pa) - 1.96 * se, (pb - pa) + 1.96 * se\n\nprint(f'Konversi A: {pa:.2%}  B: {pb:.2%}  (naik {(pb - pa) / pa:.0%} relatif)')\nprint(f'z = {z:.2f}, p-value = {p_value:.4f}')\nprint(f'Selang 95% selisih: {bawah:.2%} s.d. {atas:.2%}')\nbulanan = 250_000\nprint(f'Perkiraan tambahan pesanan/bulan: {bawah * bulanan:,.0f} s.d. {atas * bulanan:,.0f}')\nprint('Rekomendasi:', 'rilis versi B' if p_value < 0.05 and bawah > 0 else 'lanjutkan pengujian')",
  'python', run=True, kunci='hitung ukuran sampel minimum sebelum tes dimulai, dan periksa sample ratio mismatch (pembagian trafik tidak 50:50).',
  cek=q('p-value 0,02 berarti?', ['Jika sebenarnya tidak ada perbedaan, hasil seekstrem ini hanya muncul sekitar 2% kali', 'Versi B 98% lebih baik', 'Peluang B menang 2%'], 0, 'Tafsiran yang tepat untuk p-value.')),

MINI(5, 'Segmentasi pelanggan RFM',
  'Budget promo terbatas. Marketing ingin tahu pelanggan mana yang paling berharga, mana yang mulai hilang, dan mana yang baru.',
  ['Hitung Recency (hari sejak beli terakhir), Frequency (jumlah pesanan), Monetary (total belanja)', 'Skor 1–5 untuk setiap dimensi dengan kuantil', 'Petakan skor ke segmen bernama: Juara, Setia, Berisiko, Hampir Hilang, Baru', 'Ringkasan ukuran dan nilai tiap segmen beserta aksi yang disarankan'],
  ['Agregasi per pelanggan dengan <code>groupby().agg()</code>, tanggal acuan = sehari setelah transaksi terakhir.', '<code>pd.qcut(..., 5, labels=...)</code>; untuk recency labelnya dibalik (makin baru makin tinggi). Pakai <code>rank(method="first")</code> agar nilai kembar tidak membuat qcut gagal.', 'Aturan segmen sederhana berbasis skor R dan F, mudah dijelaskan ke tim marketing.', 'Tabel segmen: jumlah pelanggan, rata-rata belanja, porsi omzet.'],
  DATA_TOKO + "acuan = df['tanggal'].max() + pd.Timedelta(days=1)\nrfm = df.groupby('pelanggan').agg(R=('tanggal', lambda t: (acuan - t.max()).days), F=('id_pesanan', 'count'), M=('nilai', 'sum'))\nrfm['r'] = pd.qcut(rfm['R'].rank(method='first'), 5, labels=[5, 4, 3, 2, 1]).astype(int)\nrfm['f'] = pd.qcut(rfm['F'].rank(method='first'), 5, labels=[1, 2, 3, 4, 5]).astype(int)\n\ndef segmen(x):\n    if x.r >= 4 and x.f >= 4: return 'Juara'\n    if x.f >= 4: return 'Setia'\n    if x.r >= 4 and x.f <= 2: return 'Baru'\n    if x.r <= 2 and x.f >= 3: return 'Berisiko'\n    if x.r <= 2: return 'Hampir Hilang'\n    return 'Perlu Perhatian'\n\nrfm['segmen'] = rfm.apply(segmen, axis=1)\nring = rfm.groupby('segmen').agg(pelanggan=('M', 'size'), rata_belanja=('M', 'mean'), omzet=('M', 'sum'))\nring['porsi_omzet_%'] = (100 * ring['omzet'] / ring['omzet'].sum()).round(1)\nprint(ring.sort_values('omzet', ascending=False).round(0))\nAKSI = {'Juara': 'program loyalitas, akses produk baru', 'Berisiko': 'voucher personal + survei alasan', 'Hampir Hilang': 'kampanye win-back murah'}\nfor s, a in AKSI.items(): print(f'{s:13}: {a}')",
  'python', run=True, kunci='simpan hasil segmen ke tabel database dan pantau perpindahan segmen tiap bulan.',
  cek=q('Kenapa skor recency dibalik (5 untuk hari paling sedikit)?', ['Pelanggan yang baru saja belanja lebih berharga', 'Agar grafik lebih indah', 'Karena qcut mewajibkan'], 0, 'Recency kecil = baik.')),

